const item = $input.first();
const data = item.json.body || item.json;

let normalized = {
  channel: 'whatsapp',
  senderId: '',
  senderName: '',
  messageText: '',
  messageId: '',
  timestamp: new Date().toISOString()
};

if (data.object === 'whatsapp_business_account' || data.entry?.[0]?.changes?.[0]?.field === 'messages') {
  const entry = data.entry?.[0]?.changes?.[0]?.value;
  const msg = entry?.messages?.[0];
  normalized.channel = 'whatsapp';
  normalized.senderId = msg?.from || '';
  normalized.senderName = entry?.contacts?.[0]?.profile?.name || 'Cliente';
  normalized.messageText = msg?.text?.body || '';
  normalized.messageId = msg?.id || '';
} else if (data.object === 'instagram' || data.entry?.[0]?.messaging) {
  const messaging = data.entry?.[0]?.messaging?.[0];
  normalized.channel = 'instagram';
  normalized.senderId = messaging?.sender?.id || '';
  normalized.senderName = 'Cliente Instagram';
  normalized.messageText = messaging?.message?.text || '';
  normalized.messageId = messaging?.message?.mid || '';
} else if (data.senderId || data.messageText) {
  normalized = { ...normalized, ...data };
}

return [{ json: normalized }];

const msg = $('Normalizar Mensaje').first().json;
const memoryData = $input.first().json;

let patientContext = {
  isNewPatient: true,
  name: msg.senderName,
  senderId: msg.senderId,
  channel: msg.channel,
  conversationHistory: [],
  lastService: '',
  lastAppointment: '',
  preferences: '',
  appointmentCount: 0
};

if (memoryData && memoryData.sender_id) {
  patientContext.isNewPatient = false;
  patientContext.name = memoryData.name || msg.senderName;
  patientContext.conversationHistory = JSON.parse(memoryData.conversation_history || '[]');
  patientContext.lastService = memoryData.last_service || '';
  patientContext.lastAppointment = memoryData.last_appointment || '';
  patientContext.preferences = memoryData.preferences || '';
  patientContext.appointmentCount = parseInt(memoryData.appointment_count || '0');
}

patientContext.conversationHistory.push({
  role: 'user',
  content: msg.messageText,
  timestamp: msg.timestamp
});

if (patientContext.conversationHistory.length > 10) {
  patientContext.conversationHistory = patientContext.conversationHistory.slice(-10);
}

return [{ json: { ...msg, patientContext } }];

const aiResponse = $json.message.content;
const marker = 'AGENDAR_CITA:';
const markerIndex = aiResponse.indexOf(marker);

if (markerIndex === -1) {
  return [{ json: { ...($json), parseError: true } }];
}

const appointmentData = aiResponse.substring(markerIndex + marker.length);
const parts = appointmentData.split('|');
const [patientName, service, dateTimeStr, phone] = parts.map(p => p.trim());

let startDateTime, endDateTime;
try {
  if (dateTimeStr && dateTimeStr.match(/\d{2}\/\d{2}\/\d{4}/)) {
    const [datePart, timePart] = dateTimeStr.split(' ');
    const [day, month, year] = datePart.split('/');
    const [hour, minute] = (timePart || '10:00').split(':');
    startDateTime = new Date(parseInt(year), parseInt(month) - 1, parseInt(day), parseInt(hour), parseInt(minute));
  } else {
    startDateTime = new Date();
    startDateTime.setDate(startDateTime.getDate() + 1);
    startDateTime.setHours(10, 0, 0, 0);
  }
  endDateTime = new Date(startDateTime.getTime() + 60 * 60 * 1000);
} catch(e) {
  startDateTime = new Date();
  startDateTime.setDate(startDateTime.getDate() + 1);
  startDateTime.setHours(10, 0, 0, 0);
  endDateTime = new Date(startDateTime.getTime() + 60 * 60 * 1000);
}

const cleanMessage = aiResponse.substring(0, markerIndex).trim();

return [{
  json: {
    ...($json),
    appointmentData: {
      patientName: patientName || 'Paciente',
      service: service || 'Consulta general',
      phone: phone || '',
      startDateTime: startDateTime.toISOString(),
      endDateTime: endDateTime.toISOString(),
      startDateTimeFormatted: startDateTime.toLocaleString('es-MX', { timeZone: 'America/Mexico_City' }),
      summary: `Cita — ${service} — ${patientName}`,
      description: `Paciente: ${patientName}\nServicio: ${service}\nTeléfono: ${phone}\nAgendado vía: Agente Virtual Sofia`
    },
    cleanMessage
  }
}];

const msg = $('Normalizar Mensaje').first().json;
const context = $('Construir Contexto').first().json.patientContext;
const aiResponse = $('Sofia — Agente IA').first().json.message.content;

let appointment = null;
try {
  appointment = $('Parsear Datos de Cita').first()?.json?.appointmentData;
} catch(e) {}

const updatedHistory = [...context.conversationHistory, {
  role: 'assistant',
  content: aiResponse,
  timestamp: new Date().toISOString()
}].slice(-10);

const rowData = {
  sender_id: msg.senderId,
  name: context.name,
  channel: msg.channel,
  phone: msg.senderId,
  conversation_history: JSON.stringify(updatedHistory),
  last_message: msg.messageText,
  last_message_date: new Date().toISOString(),
  last_service: appointment?.service || context.lastService,
  last_appointment: appointment?.startDateTimeFormatted || context.lastAppointment,
  appointment_count: context.appointmentCount + (appointment ? 1 : 0),
  preferences: context.preferences,
  updated_at: new Date().toISOString()
};

return [{ json: { rowData, isNewPatient: context.isNewPatient, msg, appointment } }];

const ctx = $('Preparar Actualizacion de Memoria').first().json;
const appointment = ctx.appointment;
const channel = ctx.msg.channel;
const senderId = ctx.msg.senderId;

let responseMessage = '';

if (appointment) {
  responseMessage = `✅ ¡Tu cita está confirmada, ${ctx.msg.senderName}!\n\n📅 ${appointment.startDateTimeFormatted}\n🦷 Servicio: ${appointment.service}\n📍 Av. Paseo de la Arboleda #742, Jardines del Bosque\n\nRecibirás un recordatorio 24 horas antes. Si necesitas cambiar tu cita, solo escríbeme. ¡Hasta pronto! 😊`;
} else {
  const aiResponse = $('Sofia — Agente IA').first().json.message.content;
  responseMessage = aiResponse.replace(/AGENDAR_CITA:[^\n]*/g, '').trim();
}

return [{ json: { message: responseMessage, channel, senderId } }];
